class Solution {
public:
    bool escapeGhosts(vector<vector<int>>& ghosts, vector<int>& target) {
        int mine = abs(target[0]) + abs(target[1]);
        for (const auto& g : ghosts)
            if (abs(g[0] - target[0]) + abs(g[1] - target[1]) <= mine) return false;
        return true;
    }
};
